#include <algorithm>
#include <array>
#include <cstdint>
#include <curl/curl.h>
#include <fstream>
#include <iostream>
#include <string>
#include <vector>

namespace {

size_t write_callback(void* ptr, size_t size, size_t nmemb, void* userdata) {
    const size_t total = size * nmemb;
        auto* buffer = static_cast<std::vector<uint8_t>*>(userdata);
            const auto* bytes = static_cast<const uint8_t*>(ptr);
                buffer->insert(buffer->end(), bytes, bytes + total);
                    return total;
                    }

                    std::array<std::string, 128> build_base128_alphabet() {
                        std::array<std::string, 128> alphabet{};
                            size_t idx = 0;

                                for (int c = 33; c <= 126; ++c) {
                                        alphabet[idx++] = std::string(1, static_cast<char>(c));
                                            }

                                                for (int c = 161; c <= 194; ++c) {
                                                        std::string utf8_char;
                                                                utf8_char.push_back(static_cast<char>(0xC0 | (c >> 6)));
                                                                        utf8_char.push_back(static_cast<char>(0x80 | (c & 0x3F)));
                                                                                alphabet[idx++] = utf8_char;
                                                                                    }

                                                                                        return alphabet;
                                                                                        }

                                                                                        std::string json_escape_char(const std::string& token) {
                                                                                            if (token == "\"") return "\\\"";
                                                                                                if (token == "\\") return "\\\\";
                                                                                                    return token;
                                                                                                    }

                                                                                                    std::string json_escape_string(const std::string& input) {
                                                                                                        std::string out;
                                                                                                            out.reserve(input.size());
                                                                                                                for (char ch : input) {
                                                                                                                        if (ch == '"' || ch == '\\') out.push_back('\\');
                                                                                                                                out.push_back(ch);
                                                                                                                                    }
                                                                                                                                        return out;
                                                                                                                                        }

                                                                                                                                        }

                                                                                                                                        int main(int argc, char* argv[]) {
                                                                                                                                            if (argc < 3) {
                                                                                                                                                    return 1;
                                                                                                                                                        }

                                                                                                                                                            const std::string url = argv[1];
                                                                                                                                                                const std::string out_path = argv[2];

                                                                                                                                                                    CURL* curl = curl_easy_init();
                                                                                                                                                                        if (!curl) {
                                                                                                                                                                                return 1;
                                                                                                                                                                                    }

                                                                                                                                                                                        std::vector<uint8_t> raw_data;
                                                                                                                                                                                            curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
                                                                                                                                                                                                curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);
                                                                                                                                                                                                    curl_easy_setopt(curl, CURLOPT_USERAGENT, "Mozilla/5.0 (X11; Linux x86_64)");
                                                                                                                                                                                                        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
                                                                                                                                                                                                            curl_easy_setopt(curl, CURLOPT_WRITEDATA, &raw_data);
                                                                                                                                                                                                                curl_easy_setopt(curl, CURLOPT_TIMEOUT, 20L);

                                                                                                                                                                                                                    const CURLcode res = curl_easy_perform(curl);
                                                                                                                                                                                                                        curl_easy_cleanup(curl);

                                                                                                                                                                                                                            if (res != CURLE_OK) {
                                                                                                                                                                                                                                    return 1;
                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                            std::array<bool, 256> seen{};
                                                                                                                                                                                                                                                for (uint8_t b : raw_data) {
                                                                                                                                                                                                                                                        seen[b] = true;
                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                std::vector<uint8_t> unique_bytes;
                                                                                                                                                                                                                                                                    for (int b = 0; b < 256; ++b) {
                                                                                                                                                                                                                                                                            if (seen[b]) unique_bytes.push_back(static_cast<uint8_t>(b));
                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                    if (unique_bytes.size() < 4) {
                                                                                                                                                                                                                                                                                            unique_bytes.resize(256);
                                                                                                                                                                                                                                                                                                    for (int b = 0; b < 256; ++b) unique_bytes[b] = static_cast<uint8_t>(b);
                                                                                                                                                                                                                                                                                                        } else {
                                                                                                                                                                                                                                                                                                                std::sort(unique_bytes.begin(), unique_bytes.end());
                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                        const size_t n = unique_bytes.size();
                                                                                                                                                                                                                                                                                                                            const size_t q1 = n / 4;
                                                                                                                                                                                                                                                                                                                                const size_t q3 = n - (n / 4);

                                                                                                                                                                                                                                                                                                                                    const size_t largest_cnt = n - q3;
                                                                                                                                                                                                                                                                                                                                        const size_t smallest_cnt = q1;
                                                                                                                                                                                                                                                                                                                                            const size_t middle_cnt = q3 - q1;

                                                                                                                                                                                                                                                                                                                                                std::vector<uint8_t> byte_order;
                                                                                                                                                                                                                                                                                                                                                    byte_order.reserve(n);
                                                                                                                                                                                                                                                                                                                                                        byte_order.insert(byte_order.end(), unique_bytes.begin() + q3, unique_bytes.end());
                                                                                                                                                                                                                                                                                                                                                            byte_order.insert(byte_order.end(), unique_bytes.begin(), unique_bytes.begin() + q1);
                                                                                                                                                                                                                                                                                                                                                                byte_order.insert(byte_order.end(), unique_bytes.begin() + q1, unique_bytes.begin() + q3);

                                                                                                                                                                                                                                                                                                                                                                    std::array<uint8_t, 256> byte_to_rank{};
                                                                                                                                                                                                                                                                                                                                                                        for (size_t i = 0; i < byte_order.size(); ++i) {
                                                                                                                                                                                                                                                                                                                                                                                byte_to_rank[byte_order[i]] = static_cast<uint8_t>(i);
                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                        const auto alphabet = build_base128_alphabet();
                                                                                                                                                                                                                                                                                                                                                                                            std::string encoded_payload;
                                                                                                                                                                                                                                                                                                                                                                                                encoded_payload.reserve((raw_data.size() * 8) / 7 + 4);

                                                                                                                                                                                                                                                                                                                                                                                                    uint32_t bit_buf = 0;
                                                                                                                                                                                                                                                                                                                                                                                                        int bit_cnt = 0;
                                                                                                                                                                                                                                                                                                                                                                                                            size_t char_count = 0;

                                                                                                                                                                                                                                                                                                                                                                                                                for (uint8_t b : raw_data) {
                                                                                                                                                                                                                                                                                                                                                                                                                        const uint8_t rank = byte_to_rank[b];
                                                                                                                                                                                                                                                                                                                                                                                                                                bit_buf = (bit_buf << 8) | rank;
                                                                                                                                                                                                                                                                                                                                                                                                                                        bit_cnt += 8;
                                                                                                                                                                                                                                                                                                                                                                                                                                                while (bit_cnt >= 7) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                            bit_cnt -= 7;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const uint8_t idx = (bit_buf >> bit_cnt) & 0x7F;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    encoded_payload += json_escape_char(alphabet[idx]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ++char_count;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (bit_cnt > 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const uint8_t idx = (bit_buf << (7 - bit_cnt)) & 0x7F;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                encoded_payload += json_escape_char(alphabet[idx]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ++char_count;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                std::ofstream out(out_path, std::ios::binary);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!out) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    out << "{\n"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            << "  \"source_url\": \"" << json_escape_string(url) << "\",\n"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    << "  \"original_length\": " << raw_data.size() << ",\n"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            << "  \"partition_counts\": {\"largest_25\": " << largest_cnt
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    << ", \"smallest_25\": " << smallest_cnt
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            << ", \"middle_50\": " << middle_cnt << "},\n"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    << "  \"byte_order\": [";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        for (size_t i = 0; i < byte_order.size(); ++i) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                out << static_cast<int>(byte_order[i]) << (i + 1 < byte_order.size() ? "," : "");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        out << "],\n  \"alphabet\": \"";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            for (const auto& sym : alphabet) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    out << json_escape_char(sym);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            out << "\",\n  \"encoded_payload\": \"" << encoded_payload << "\",\n"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    << "  \"encoded_chars\": " << char_count << "\n}\n";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        